SELECT p.payment_order_id AS paymentOrderId, p.order_no AS orderNo, p.customer_name AS customerName, CONCAT('¥', FORMAT(p.amount, 2)) AS amount, p.payment_method AS paymentMethod, p.channel_code AS channel, p.channel_transaction_no AS channelTransactionNo, p.status, p.status_type AS statusType, pa.attempt_status AS latestAttemptStatus, DATE_FORMAT(p.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt FROM t_payment_order p LEFT JOIN t_payment_attempt pa ON pa.id = ( SELECT latest_pa.id FROM t_payment_attempt latest_pa WHERE latest_pa.payment_order_id = p.payment_order_id ORDER BY latest_pa.created_at DESC, latest_pa.id DESC LIMIT 1 )
p.payment_order_id LIKE CONCAT('%', #{query.paymentOrderId}, '%')
AND p.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND p.channel_code = #{query.channelCode}
AND p.payment_method = #{query.paymentMethod}
AND
AND p.status = 'SUCCESS' AND p.success_at IS NULL
AND p.status IN ('PREPAY_CREATED', 'WAIT_CALLBACK', 'RISK_REVIEW')
AND p.status = #{query.status}
LIMIT #{query.limit} OFFSET #{query.offset}

