mapper.update:
UPDATE t_payment_order
SET status = #{status},
    status_type = #{statusType},
    channel_transaction_no = #{channelTransactionNo}
WHERE payment_order_id = #{paymentOrderId}

UPDATE t_payment_order
SET status = 'WAIT_CALLBACK',
    status_type = 'warn',
    channel_transaction_no = #{channelTransactionNo}
WHERE payment_order_id = #{paymentOrderId}
  AND status = 'WAIT_CALLBACK'
  AND (
    NULLIF(TRIM(channel_transaction_no), '') IS NULL
    OR channel_transaction_no = #{channelTransactionNo}
  )
  AND EXISTS (
    SELECT 1
    FROM t_payment_attempt submitted_attempt
    WHERE submitted_attempt.payment_order_id = t_payment_order.payment_order_id
  )

UPDATE t_prepay_order
SET cashier_status = #{cashierStatus},
    cashier_status_type = #{cashierStatusType}
WHERE payment_order_id = #{paymentOrderId}

UPDATE t_payment_order
SET payment_method = #{paymentMethod},
    channel_code = #{channelCode},
    channel_transaction_no = #{channelTransactionNo}
WHERE payment_order_id = #{paymentOrderId}
  AND status = 'WAIT_CALLBACK'
  AND channel_code = #{channelCode}
  AND (
    NULLIF(TRIM(channel_transaction_no), '') IS NULL
    OR channel_transaction_no = #{channelTransactionNo}
  )

UPDATE t_payment_attempt
SET attempt_status = #{attemptStatus},
    attempt_status_type = #{attemptStatusType}
WHERE id = (
    SELECT latest_attempt.id
    FROM (
        SELECT id
        FROM t_payment_attempt
        WHERE payment_order_id = #{paymentOrderId}
        ORDER BY created_at DESC, id DESC
        LIMIT 1
    ) latest_attempt
)

UPDATE t_order
SET paid_amount = #{paidAmount},
    order_status = #{orderStatus},
    order_status_type = #{orderStatusType}
WHERE order_no = #{orderNo}

UPDATE t_bill
SET paid_amount = #{paidAmount},
    bill_status = #{billStatus},
    bill_status_type = #{billStatusType}
WHERE bill_no = #{billNo}

UPDATE t_payment_route_record
SET ops_config_snapshot_version = #{snapshotVersion}
WHERE route_no = #{routeNo}

UPDATE t_payment_attempt
SET ops_config_snapshot_version = #{snapshotVersion}
WHERE attempt_no = #{attemptNo}

